    // Each row/column is independent, so we parallelize the *outer*
    // loops over rows/columns with std::thread while keeping the inner
    // loops sequential to preserve the recurrence within each line.
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j]
    //   Halide here:  imgIn(j, i)
    // where i in [0, w) and j in [0, h).
    // --------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // 1) Horizontal forward recursion (left -> right).
    //    Independent over 'i' (rows), so we parallelize over i.
    parallel_for_1d(0, w, [&](int i_row) {
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);
        num_t xm1 = num_t(0);

        for (int j_col = 0; j_col < h; ++j_col) {
            num_t x_ij = imgIn(j_col, i_row);
            num_t y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1(j_col, i_row) = y_ij;

            xm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    });

    // 2) Horizontal backward recursion (right -> left).
    //    Also independent over 'i', so we parallelize over i.
    parallel_for_1d(0, w, [&](int i_row) {
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);
        num_t xp1 = num_t(0);
        num_t xp2 = num_t(0);

        for (int j_col = h - 1; j_col >= 0; --j_col) {
            num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2(j_col, i_row) = y_ij;

            xp2 = xp1;
            xp1 = imgIn(j_col, i_row);
            yp2 = yp1;
            yp1 = y_ij;
        }
    });

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    combine1.realize(imgOut);

    // 4) Vertical forward recursion (top -> bottom).
    //    Independent over 'j' (columns), so we parallelize over j.
    parallel_for_1d(0, h, [&](int j_col) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

        for (int i_row = 0; i_row < w; ++i_row) {
            num_t x_ij = imgOut(j_col, i_row);
            num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1(j_col, i_row) = y_ij;

            tm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    });

    // 5) Vertical backward recursion (bottom -> top).
    //    Also independent over 'j', so we parallelize over j.
    parallel_for_1d(0, h, [&](int j_col) {
        num_t tp1 = num_t(0);
        num_t tp2 = num_t(0);
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);

        for (int i_row = w - 1; i_row >= 0; --i_row) {
            num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2(j_col, i_row) = y_ij;

            tp2 = tp1;
            tp1 = imgOut(j_col, i_row);
            yp2 = yp1;
            yp1 = y_ij;
        }
    });

    // 6) Final pointwise combination:
    //    imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    combine2.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Output and timing, similar style to example/gemm.cpp.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; ++i) {
            for (int j = 0; j < h; ++j) {
                // Original C prints imgOut[i][j]; here we map to imgOut(j, i).
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
