    Expr denom = cast<num_t>(Expr(65535.0f));
    init_in(j, i) = cast<num_t>(val) / denom;

    // imgOut is not initialized in the original C code, but we'll
    // set it to zero for completeness.
    init_out(j, i) = cast<num_t>(Expr(0));

    // -----------------------------------------------------------------
    // Schedule for initialization:
    //  - j (x) is the contiguous dimension -> vectorize across j
    //  - i (y) is outer -> parallelize across scanlines
    //
    // This gives good memory access patterns and uses all cores.
    // -----------------------------------------------------------------
    init_in
        .reorder(j, i)
        .vectorize(j, kVectorWidth)
        .parallel(i);

    init_out
        .reorder(j, i)
        .vectorize(j, kVectorWidth)
        .parallel(i);

    // Fill the buffers.
    init_in.realize(imgIn);
    init_out.realize(imgOut);
