    // Schedule for the pointwise combinations.
    //
    // We use a row-major traversal:
    //   - x is the contiguous dimension (dim 0 of Buffer -> j in C code)
    //   - y is the scanline index (dim 1 -> i in C code)
    //
    // We vectorize across x and parallelize across y to exploit SIMD
    // and multiple cores. This is where Halide's scheduling gives
    // the most benefit, since these passes are embarrassingly parallel.
    // --------------------------------------------------------------------
    combine1
        .reorder(x, y)           // innermost x, outermost y
        .vectorize(x, kVectorWidth)
        .parallel(y);

    combine2
        .reorder(x, y)
        .vectorize(x, kVectorWidth)
        .parallel(y);

