            num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            xp2 = xp1;
            xp1 = imgIn(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    //    This is a purely pointwise stage, so we express and schedule
    //    it in Halide (see combine1's schedule above) to exploit
    //    SIMD and multithreading.
    y1_param.set(y1);
    y2_param.set(y2);
    combine1.realize(imgOut);

    // 4) Vertical forward recursion (top -> bottom).
    //    Here we have recurrences along the "i" direction for each
    //    fixed column j. The access pattern is strided in memory
    //    (we step in dim 1 of the Buffer), but the dependency
    //    structure prohibits simple tiling or vectorization without
    //    changing the algorithmic complexity, so we leave this as a
    //    straightforward set of scalar loops.
    for (int j = 0; j < h; ++j) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

