    for (int i = 0; i < w; ++i) {
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);
        num_t xp1 = num_t(0);
        num_t xp2 = num_t(0);

        num_t *in_ptr = &imgIn(0, i);
        num_t *y2_ptr = &y2(0, i);

        for (int j = h - 1; j >= 0; --j) {
            num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2_ptr[j] = y_ij;

            xp2 = xp1;
            xp1 = in_ptr[j];
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    combine1.realize(imgOut);

    // 4) Vertical forward recursion (top -> bottom).
    //    We step along the slow dimension with explicit pointers and strides.
    for (int j = 0; j < h; ++j) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

        num_t *out_ptr = &imgOut(j, 0);
        num_t *y1_ptr  = &y1(j, 0);

        for (int i = 0; i < w; ++i) {
            num_t x_ij = *out_ptr;
            num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
            *y1_ptr = y_ij;

            tm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;

            out_ptr += stride_imgOut_y;
            y1_ptr  += stride_y1_y;
        }
    }

    // 5) Vertical backward recursion (bottom -> top).
    for (int j = 0; j < h; ++j) {
        num_t tp1 = num_t(0);
        num_t tp2 = num_t(0);
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);

        // Start from bottom of the column.
        num_t *out_ptr = &imgOut(j, w - 1);
        num_t *y2_ptr  = &y2(j, w - 1);

        for (int i = w - 1; i >= 0; --i) {
            num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            *y2_ptr = y_ij;

            tp2 = tp1;
            tp1 = *out_ptr;
            yp2 = yp1;
            yp1 = y_ij;

            out_ptr -= stride_imgOut_y;
            y2_ptr  -= stride_y2_y;
        }
    }

    // 6) Final pointwise combination:
    //    imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    combine2.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Output and timing, similar style to example/gemm.cpp.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; ++i) {
            for (int j = 0; j < h; ++j) {
                // Original C prints imgOut[i][j]; here we map to imgOut(j, i).
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
